static int32_t javaCosine(int32_t from, int32_t to, int32_t d, int32_t t) {
  if (t <= 0) return from;
  if (t >= d) return to;
  double w = (1 - cos(M_PI * t / d)) / 2;
  return (int32_t)floor(from + (to - from) * w + 0.5);
}
static int32_t javaLinear(int32_t from, int32_t to, int32_t d, int32_t t) {
  long long c = t < 0 ? 0 : (t > d ? d : t);
  long long delta = (long long)to - from;
  long long num = 2 * delta * c + d, den = 2LL * d;
  long long q = num / den;
  if ((num % den != 0) && ((num < 0) != (den < 0))) q--;
  return (int32_t)(from + q);
}

static void testValues() {
  // Version-2 definition with the former version-1 fade tracks and the catalogue shapes (a linear
  // blink and a pattern repeated inside a cycle): constant 0, constant 80, near, far, blink, double.
  static Definition def;
  const struct { KiteWindProto::Curve curve; uint16_t count; } tracks[] = {
      {KiteWindProto::Curve::Constant, 1}, {KiteWindProto::Curve::Constant, 1}, {KiteWindProto::Curve::Cosine, 3},
      {KiteWindProto::Curve::Cosine, 3},   {KiteWindProto::Curve::Linear, 2},   {KiteWindProto::Curve::Cosine, 3}};
  const KiteWindProto::Segment segments[] = {
      {1, 0, 0},
      {1, 80, 80},
      {1750, 0, 50}, {1750, 50, 0}, {1500, 0, 0},
      {1000, 0, 30}, {1000, 30, 0}, {3000, 0, 0},
      {1000, 100, 100}, {1000, 0, 0},
      {200, 0, 100}, {200, 100, 0}, {9600, 0, 0}};
  def.trackCount = 6;
  def.segmentCount = 13;
  for (uint8_t t = 0; t < def.trackCount; t++) {
    def.tracks[t].curve = tracks[t].curve;
    def.tracks[t].firstSegment = t ? static_cast<uint16_t>(def.tracks[t - 1].firstSegment + def.tracks[t - 1].segmentCount) : 0;
    def.tracks[t].segmentCount = tracks[t].count;
  }
  memcpy(def.segments, segments, sizeof(segments));
  const Track& near = def.tracks[2];
  const Track& far = def.tracks[3];
  // Expected values computed with Java's formula: near fade peaks at 50.
  CHECK(trackValueAt(def, near, 0) == 0);
  CHECK(trackValueAt(def, near, 1) == 0);
  CHECK(trackValueAt(def, near, 875) == 25);
  CHECK(trackValueAt(def, near, 1749) == 50);
  CHECK(trackValueAt(def, near, 1750) == 50);
  CHECK(trackValueAt(def, near, 2625) == 25);
  CHECK(trackValueAt(def, near, 3499) == 0);
  CHECK(trackValueAt(def, near, 3500) == 0);
  CHECK(trackValueAt(def, near, 4999) == 0);
  CHECK(trackValueAt(def, near, 5000) == 0);   // after the end: last "to"
  CHECK(trackValueAt(def, near, -7) == 0);     // before 0: first "from"
  CHECK(trackValueAt(def, far, 500) == 15);
  CHECK(trackValueAt(def, far, 1000) == 30);
  CHECK(trackValueAt(def, far, 1500) == 15);
  CHECK(trackValueAt(def, far, 2000) == 0);
  CHECK(trackValueAt(def, def.tracks[1], 123456) == 80);
  CHECK(trackValueAt(def, def.tracks[0], 123456) == 0);
  CHECK(trackValueAt(def, def.tracks[4], 999) == 100);
  CHECK(trackValueAt(def, def.tracks[4], 1000) == 0);
  CHECK(trackValueAt(def, def.tracks[5], 200) == 100);
  CHECK(trackValueAt(def, def.tracks[5], 400) == 0);
  CHECK(trackValueAt(def, def.tracks[5], 9999) == 0);
  // Linear matches Java exactly, including negative deltas and half-up ties.
  CHECK(linearValue(0, 100, 1000, 500) == 50);
  CHECK(linearValue(0, 1, 2, 1) == 1);     // 0.5 rounds up
  CHECK(linearValue(1, 0, 2, 1) == 1);     // 1 + floor(-0.5 + 0.5)... Java: 1 + floorDiv(-2+2,4)=1
  CHECK(linearValue(10, 0, 4, 1) == 8);    // 7.5 -> 8
  CHECK(linearValue(10, 0, 4, 99) == 0 && linearValue(10, 0, 4, -3) == 10);
  int mismatches = 0, maxDiff = 0, samples = 0;
  // Linear: exhaustive-ish comparison with the Java rules.
  for (int d = 1; d <= 40; d++)
    for (int from = 0; from <= 12; from++)
      for (int to = 0; to <= 12; to++)
        for (int t = -2; t <= d + 2; t++) CHECK(linearValue(from, to, d, t) == javaLinear(from, to, d, t));
  // Cosine tolerance: equal to the double formula except within ~1e-7 of a rounding tie.
  const int32_t deltas[][2] = {{0, 50}, {50, 0}, {0, 30}, {30, 0}, {0, 100}, {100, 0}, {0, 255},
                               {7, 1000000}, {1000000, 0}, {3, 999999}};
  const int32_t durations[] = {2, 3, 7, 1000, 1750, 1749, 2000, 2500, 86400000 / 1000};
  for (size_t a = 0; a < sizeof(deltas) / sizeof(deltas[0]); a++)
    for (size_t b = 0; b < sizeof(durations) / sizeof(durations[0]); b++)
      for (int32_t t = -1; t <= durations[b] + 1; t += (durations[b] > 5000 ? 7 : 1)) {
        int32_t got = cosineValue(deltas[a][0], deltas[a][1], durations[b], t);
        int32_t want = javaCosine(deltas[a][0], deltas[a][1], durations[b], t);
        int diff = abs(got - want);
        samples++;
        if (diff) mismatches++;
        if (diff > maxDiff) maxDiff = diff;
      }
  printf("cosine vs Java double: %d samples, %d mismatches, max diff %d\n", samples, mismatches, maxDiff);
  CHECK(maxDiff <= 1);
  CHECK(mismatches * 200 <= samples);  // 0.5 percent at most, only for deltas near 1e6
  // Deltas up to 255 (every real profile): any difference from Java must sit on an exact real
  // rounding tie (for example t/d = 1/2 or 1/3), where Java's own result is floating-point noise.
  int tieOnly = 0, offTie = 0;
  for (int32_t delta = 1; delta <= 255; delta += 2)
    for (int32_t d = 2; d <= 600; d += 23)
      for (int32_t t = 1; t < d; t++) {
        double w = (1 - cos(M_PI * t / d)) / 2;
        double ex = delta * w + 0.5;
        double tieDistance = fabs(ex - floor(ex + 0.5));
        int32_t j = javaCosine(0, delta, d, t);
        int32_t g = cosineValue(0, delta, d, t);
        if (g != j) (tieDistance < 1e-6 ? tieOnly : offTie)++;
        // Descending ramps (from > to) round the same way.
        int32_t jd = javaCosine(delta, 0, d, t);
        int32_t gd = cosineValue(delta, 0, d, t);
        if (gd != jd) (tieDistance < 1e-6 ? tieOnly : offTie)++;
      }
  printf("cosine small-delta differences: %d on exact ties, %d elsewhere\n", tieOnly, offTie);
  CHECK(offTie == 0);
  // The default profile (deltas up to 100, durations 1000/1750) matches exactly everywhere.
  for (int32_t t = 0; t <= 1750; t++) {
    CHECK(cosineValue(0, 50, 1750, t) == javaCosine(0, 50, 1750, t));
    CHECK(cosineValue(50, 0, 1750, t) == javaCosine(50, 0, 1750, t));
  }
  for (int32_t t = 0; t <= 1000; t++) {
    CHECK(cosineValue(0, 30, 1000, t) == javaCosine(0, 30, 1000, t));
    CHECK(cosineValue(30, 0, 1000, t) == javaCosine(30, 0, 1000, t));
  }
  CHECK(cosineValue(5, 9, 100, 0) == 5 && cosineValue(5, 9, 100, 100) == 9);
}


static uint8_t wire[KiteWindProto::MAX_RESPONSE_BYTES];
static Engine engine;
static Rgb px[52];

static KiteWindProto::Error stage(const Spec& spec) {
  size_t n = KiteWindProtoSample::build(spec, wire, sizeof(wire));
  CHECK(engine.beginStage());
  KiteWindProto::Error e = KiteWindProto::decodeBuffer(wire, n, engine.stagedFrame(), engine.stagedDefinition());
  engine.endStage(e == KiteWindProto::Error::Ok);
  return e;
}

static void testActivationAndDigest() {
  CHECK(!engine.hasFrame());
  engine.render(0, px, 52);
  CHECK(px[1].r == 0);  // restart: spot lamps off
  Spec noDef;
  noDef.definition = false;
  CHECK(stage(noDef) == KiteWindProto::Error::Ok);
  KiteWindProto::Error why = KiteWindProto::Error::Ok;
  CHECK(engine.activate(&why) == Activation::Rejected && why == KiteWindProto::Error::NoDefinition);
  Spec full;
  full.brightness = 255;
  CHECK(stage(full) == KiteWindProto::Error::Ok);
  CHECK(engine.activate() == Activation::Activated);
  CHECK(engine.hasFrame() && engine.lampCount() == 51 && engine.brightness() == 255);
  // Digest match without a definition keeps the definition and takes the new lamps.
  noDef.brightness = 125;
  CHECK(stage(noDef) == KiteWindProto::Error::Ok);
  CHECK(engine.activate() == Activation::Activated && engine.brightness() == 125);
  // A different digest without a definition is rejected; the previous state stays.
  Spec other;
  other.definition = false;
  other.digestSeed = 7;  // proto_sample.h knob: digest bytes differ from the default
  other.brightness = 50;
  CHECK(stage(other) == KiteWindProto::Error::Ok);
  why = KiteWindProto::Error::Ok;
  CHECK(engine.activate(&why) == Activation::Rejected && why == KiteWindProto::Error::DigestMismatch);
  CHECK(engine.brightness() == 125);
}

static void testRejectedKeepsPrevious() {
  Spec full;
  full.brightness = 200;
  stage(full);
  engine.activate();
  Spec small;
  small.tracks = 3;
  small.segments = 3;
  small.track = 2;
  small.definition = true;
  small.brightness = 10;
  CHECK(stage(small) == KiteWindProto::Error::Ok);
  CHECK(engine.activate() == Activation::Activated);
  // Lamps that point past the active definition are rejected at activation.
  Spec bad;
  bad.definition = false;
  bad.track = 20;
  bad.brightness = 90;
  CHECK(stage(bad) == KiteWindProto::Error::Ok);
  KiteWindProto::Error why = KiteWindProto::Error::Ok;
  CHECK(engine.activate(&why) == Activation::Rejected && why == KiteWindProto::Error::BadTrackRef);
  CHECK(engine.brightness() == 10);
  // A failed decode leaves nothing staged.
  Spec broken;
  broken.contract = 1;
  CHECK(stage(broken) == KiteWindProto::Error::UnsupportedVersion);
  CHECK(engine.activate() == Activation::Nothing && engine.brightness() == 10);
}

static void testBrightnessScaling() {
  // Every segment of the animated track holds 100%, so any time gives full level.
  Spec s;
  s.track = 2;
  s.rgb = 0xFF8000;
  s.brightness = 255;
  s.duration = 1000;
  s.from = 100;
  s.to = 100;
  stage(s);
  engine.activate();
  engine.render(5000, px, 52);  // any time inside a 100% segment after the first one
  CHECK(px[1].r == 255 && px[1].g == 128 && px[1].b == 0);
  s.definition = false;
  s.brightness = 128;
  stage(s);
  engine.activate();
  engine.render(5000, px, 52);
  CHECK(px[1].r == 128 && px[1].g == 64);  // (255*128*100+12750)/25500 = 128; (128*128*100+12750)/25500 = 64
  s.brightness = 0;
  stage(s);
  engine.activate();
  engine.render(5000, px, 52);
  CHECK(px[1].r == 0 && px[1].g == 0);  // night 0% turns spot lamps off
  engine.clearLamps();
  engine.render(5000, px, 52);
  CHECK(px[1].r == 0 && !engine.hasFrame() && engine.hasDefinition());
}

// Staged updates that are never activated, short outputs, pixel 0 and the millis() rollover.
static void testPlayerSafety() {
  Spec s;
  s.track = 1;  // constant track: segment 1 holds s.from percent
  s.from = 100;
  s.to = 100;
  s.brightness = 255;
  CHECK(stage(s) == KiteWindProto::Error::Ok);
  CHECK(!engine.beginStage());  // an update waiting for activation blocks the next one
  engine.discard();             // late or retired exchange
  CHECK(engine.activate() == Activation::Nothing);
  CHECK(engine.beginStage());
  engine.discard();             // no effect while the network task is writing
  CHECK(!engine.beginStage());
  engine.endStage(false);
  CHECK(stage(s) == KiteWindProto::Error::Ok);
  CHECK(engine.activate() == Activation::Activated);
  // Lamps outside the output are skipped; nothing is written past `count`.
  memset(px, 0x5A, sizeof(px));
  engine.render(100, px, 10);
  CHECK(px[0].r == 0 && px[1].r == 255 && px[9].r == 255);
  for (size_t i = 10; i < 52; i++) CHECK(px[i].r == 0x5A && px[i].g == 0x5A && px[i].b == 0x5A);
  engine.render(100, px, 52);
  CHECK(px[0].r == 0 && px[0].g == 0 && px[0].b == 0);  // pixel 0 belongs to the controller
  CHECK(px[51].r == 255);
  // An animation keeps its phase across the millis() rollover.
  Spec w;
  w.tracks = 3;
  w.segments = 4;  // track 2: two 1000 ms segments
  w.track = 2;
  w.from = 0;
  w.to = 100;
  w.brightness = 255;
  static Engine wrap;
  size_t n = KiteWindProtoSample::build(w, wire, sizeof(wire));
  CHECK(wrap.beginStage());
  wrap.endStage(KiteWindProto::decodeBuffer(wire, n, wrap.stagedFrame(), wrap.stagedDefinition()) == KiteWindProto::Error::Ok);
  CHECK(wrap.activate() == Activation::Activated);
  Rgb before[52], after[52];
  wrap.render(0xFFFFFE0Cu, before, 52);                          // 500 ms before the rollover
  wrap.render(static_cast<uint32_t>(0xFFFFFE0Cu + 2000u), after, 52);  // one 2000 ms cycle later
  CHECK(before[1].r == after[1].r && before[1].g == after[1].g);
}

static void testSizes() {
  printf("Engine %u bytes (two definitions and two frames)\n", static_cast<unsigned>(sizeof(Engine)));
  CHECK(sizeof(Engine) < 4096);
}

int main() {
  testValues();
  testActivationAndDigest();
  testRejectedKeepsPrevious();
  testBrightnessScaling();
  testPlayerSafety();
  testSizes();
  printf("%d checks, %d failures\n", checks, failures);
  return failures ? 1 : 0;
}
